use split_decls_genesis :: ourprelude :: * ; const RED_ZONE : usize = 100 * 1024 ; #[cfg (not (target_os = "aix"))] const STACK_PER_RECURSION : usize = 1024 * 1024 ; #[cfg (target_os = "aix")] const STACK_PER_RECURSION : usize = 16 * 1024 * 1024 ; #[doc = " Grows the stack on demand to prevent stack overflow. Call this in strategic locations"] #[doc = " to \"break up\" recursive calls. E.g. almost any call to `visit_expr` or equivalent can benefit"] #[doc = " from this."] #[doc = ""] #[doc = " Should not be sprinkled around carelessly, as it causes a little bit of overhead."] #[inline] pub fn ensure_sufficient_stack < R > (f : impl FnOnce () -> R) -> R { stacker :: maybe_grow (RED_ZONE , STACK_PER_RECURSION , f) }